#include "bleskernos_api.h"
#include <SDL2/SDL.h>
#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static Uint16 little16(const Uint8 *p){return(Uint16)(p[0]|((Uint16)p[1]<<8));}
static Uint32 little32(const Uint8 *p){return(Uint32)p[0]|((Uint32)p[1]<<8)|((Uint32)p[2]<<16)|((Uint32)p[3]<<24);}
SDL_Surface *SDL_LoadBMP(const char *path){FILE*f;Uint8 header[54];SDL_Surface*s=0;Uint8*row=0;if(!path||(f=fopen(path,"rb"))==0)return 0;if(fread(header,1,sizeof(header),f)!=sizeof(header)||header[0]!='B'||header[1]!='M'||little32(header+30)!=0)goto done;Uint32 offset=little32(header+10),width=little32(header+18),height=little32(header+22);Uint16 bits=little16(header+28);if(!width||!height||(bits!=24&&bits!=32)||width>4096||height>4096)goto done;s=SDL_CreateRGBSurfaceWithFormat(0,(int)width,(int)height,32,SDL_PIXELFORMAT_ARGB8888);if(!s)goto done;Uint32 row_size=((width*(bits/8U))+3U)&~3U;row=(Uint8*)malloc(row_size);if(!row){SDL_FreeSurface(s);s=0;goto done;}if(fseek(f,(long)offset,SEEK_SET)<0){SDL_FreeSurface(s);s=0;goto done;}for(Uint32 y=0;y<height;y++){if(fread(row,1,row_size,f)!=row_size){SDL_FreeSurface(s);s=0;goto done;}Uint32*out=(Uint32*)((Uint8*)s->pixels+(height-1U-y)*(Uint32)s->pitch);for(Uint32 x=0;x<width;x++){Uint8*b=row+x*(bits/8U);out[x]=((bits==32?(Uint32)b[3]:255U)<<24)|((Uint32)b[2]<<16)|((Uint32)b[1]<<8)|b[0];}}done:free(row);fclose(f);return s;}

typedef struct {int open,paused,stop;SDL_AudioSpec spec;pthread_t thread;Uint8*buffer;Uint8*pcm;Uint8*queued;Uint32 queued_size,queued_capacity;} audio_state_t;
static audio_state_t audio;
static void convert_audio(audio_state_t*a,int bytes){if(a->spec.format==AUDIO_U8&&a->spec.channels==1){memcpy(a->pcm,a->buffer,bytes);return;}int frames=bytes/((a->spec.format==AUDIO_S16LSB?2:1)*a->spec.channels);for(int i=0;i<frames;i++){int sample=0;for(int c=0;c<a->spec.channels;c++){if(a->spec.format==AUDIO_S16LSB){int j=(i*a->spec.channels+c)*2;short v=(short)(a->buffer[j]|((Uint16)a->buffer[j+1]<<8));sample+=(v>>8)+128;}else sample+=a->buffer[i*a->spec.channels+c];}a->pcm[i]=(Uint8)(sample/a->spec.channels);}}
static void *audio_worker(void*unused){(void)unused;while(!audio.stop){if(audio.paused){SDL_Delay(2);continue;}int bytes=audio.spec.samples*audio.spec.channels*(audio.spec.format==AUDIO_S16LSB?2:1);memset(audio.buffer,audio.spec.silence,bytes);if(audio.queued_size){Uint32 take=audio.queued_size<(Uint32)bytes?audio.queued_size:(Uint32)bytes;memcpy(audio.buffer,audio.queued,take);memmove(audio.queued,audio.queued+take,audio.queued_size-take);audio.queued_size-=take;}else if(audio.spec.callback)audio.spec.callback(audio.spec.userdata,audio.buffer,bytes);else{SDL_Delay(2);continue;}convert_audio(&audio,bytes);Uint32 frames=(Uint32)bytes/(audio.spec.channels*(audio.spec.format==AUDIO_S16LSB?2U:1U));if(!bk_sound_play_pcm_u8(audio.pcm,frames,(Uint16)audio.spec.freq,255)){SDL_Delay(10);continue;}SDL_Delay((frames*1000U)/(Uint32)audio.spec.freq+1U);}return 0;}
SDL_AudioDeviceID SDL_OpenAudioDevice(const char*device,int capture,const SDL_AudioSpec*d,SDL_AudioSpec*o,int changes){(void)device;(void)changes;if(capture||!d||audio.open||!bk_sound_pcm_available()||d->freq<4000||d->freq>48000||(d->format!=AUDIO_U8&&d->format!=AUDIO_S16LSB)||(d->channels!=1&&d->channels!=2))return 0;memset(&audio,0,sizeof(audio));audio.spec=*d;if(!audio.spec.samples)audio.spec.samples=1024;audio.spec.silence=d->format==AUDIO_U8?128:0;audio.spec.size=audio.spec.samples*audio.spec.channels*(audio.spec.format==AUDIO_S16LSB?2U:1U);audio.buffer=(Uint8*)malloc(audio.spec.size);audio.pcm=(Uint8*)malloc(audio.spec.samples);audio.queued_capacity=audio.spec.size*8U;audio.queued=(Uint8*)malloc(audio.queued_capacity);if(!audio.buffer||!audio.pcm||!audio.queued){free(audio.buffer);free(audio.pcm);free(audio.queued);memset(&audio,0,sizeof(audio));return 0;}audio.open=1;audio.paused=1;if(o)*o=audio.spec;if(pthread_create(&audio.thread,0,audio_worker,0)!=0){SDL_CloseAudioDevice(1);return 0;}return 1;}
void SDL_CloseAudioDevice(SDL_AudioDeviceID d){if(d!=1||!audio.open)return;audio.stop=1;(void)pthread_join(audio.thread,0);bk_sound_stop();free(audio.buffer);free(audio.pcm);free(audio.queued);memset(&audio,0,sizeof(audio));}
void SDL_PauseAudioDevice(SDL_AudioDeviceID d,int paused){if(d==1&&audio.open)audio.paused=paused!=0;}
int SDL_QueueAudio(SDL_AudioDeviceID d,const void*data,Uint32 length){if(d!=1||!audio.open||(!data&&length)){errno=EINVAL;return-1;}if(length>audio.queued_capacity-audio.queued_size){Uint32 capacity=audio.queued_capacity;while(capacity-audio.queued_size<length)capacity*=2U;Uint8*p=(Uint8*)realloc(audio.queued,capacity);if(!p)return-1;audio.queued=p;audio.queued_capacity=capacity;}memcpy(audio.queued+audio.queued_size,data,length);audio.queued_size+=length;return 0;}
Uint32 SDL_GetQueuedAudioSize(SDL_AudioDeviceID d){return d==1&&audio.open?audio.queued_size:0;}void SDL_ClearQueuedAudio(SDL_AudioDeviceID d){if(d==1&&audio.open)audio.queued_size=0;}
int SDL_OpenAudio(SDL_AudioSpec*d,SDL_AudioSpec*o){return SDL_OpenAudioDevice(0,0,d,o,0)?0:-1;}void SDL_CloseAudio(void){SDL_CloseAudioDevice(1);}void SDL_PauseAudio(int paused){SDL_PauseAudioDevice(1,paused);}
